static int create_empty(const char*p,mode_t m){int fd=open(p,O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC,m);if(fd<0)return -1;int rc=fsync(fd),e=errno;if(close(fd)<0&&rc==0){rc=-1;e=errno;}errno=e;return rc;}
int cvc_repo_init_here(void){char*cwd=cvc_getcwd_alloc();if(!cwd)return cvc_errorf("cannot determine current directory");char*cvc=cvc_path_join(cwd,".cvc");struct stat st;if(lstat(cvc,&st)==0){free(cwd);free(cvc);return cvc_errorf(".cvc already exists");}if(errno!=ENOENT){int e=errno;free(cwd);free(cvc);return cvc_errorf("cannot inspect .cvc: %s",strerror(e));}int made=0,rc=-1;if(mkdir(cvc,0777)<0){cvc_errorf("cannot create .cvc: %s",strerror(errno));goto out;}made=1;char*refs=cvc_path_join(cvc,"refs"),*heads=cvc_path_join(refs,"heads"),*objs=cvc_path_join(cvc,"objects"),*state=cvc_path_join(cvc,"state"),*lock=cvc_path_join(cvc,"lock"),*head=cvc_path_join(cvc,"HEAD"),*mainp=cvc_path_join(heads,"main"),*cfg=cvc_path_join(cvc,"config.json");if(mkdir(refs,0777)<0||mkdir(heads,0777)<0||mkdir(objs,0777)<0||mkdir(state,0777)<0||create_empty(lock,0666)<0||create_empty(mainp,0666)<0){cvc_errorf("initialization failed: %s",strerror(errno));goto cleanvars;}static const char hv[]="ref: refs/heads/main\n";static const char cv[]="{\"format_version\":1}\n";if(cvc_atomic_write(head,hv,sizeof(hv)-1,0666)<0||cvc_atomic_write(cfg,cv,sizeof(cv)-1,0666)<0){cvc_errorf("initialization failed: %s",strerror(errno));goto cleanvars;}if(cvc_fsync_parent(head)<0){cvc_errorf("initialization durability failure: %s",strerror(errno));goto cleanvars;}printf("Initialized CVC repository in %s\n",cwd);rc=0;cleanvars:free(refs);free(heads);free(objs);free(state);free(lock);free(head);free(mainp);free(cfg);out:if(rc<0&&made&&cvc_remove_tree_nofollow(cvc)<0)cvc_warnf("could not fully remove failed initialization metadata");free(cwd);free(cvc);return rc;}

static char*find_root(void){char*cur=cvc_getcwd_alloc();if(!cur)return NULL;for(;;){char*p=cvc_path_join(cur,".cvc");struct stat st;if(lstat(p,&st)==0&&S_ISDIR(st.st_mode)){free(p);return cur;}free(p);if(!strcmp(cur,"/"))break;char*up=cvc_path_dirname(cur);free(cur);cur=up;}free(cur);errno=ENOENT;return NULL;}
static int require_dir(const char*p,const char*name){struct stat st;if(lstat(p,&st)<0||!S_ISDIR(st.st_mode))return cvc_errorf("repository integrity: %s must be a real directory",name);return 0;}
static int require_reg(const char*p,const char*name){struct stat st;if(lstat(p,&st)<0||!S_ISREG(st.st_mode))return cvc_errorf("repository integrity: %s must be a real regular file",name);return 0;}
static int validate_intermediate_dirs(const char*base,const char*rel){
    char *copy=cvc_xstrdup(rel);
    char *cur=cvc_xstrdup(base);
    char *p=copy;
    for(;;){
        char *slash=strchr(p,'/');
        if(!slash)break;
        *slash=0;
        char *n=cvc_path_join(cur,p);
        free(cur); cur=n;
        if(require_dir(cur,"branch ref intermediate directory")<0){free(cur);free(copy);return -1;}
        p=slash+1;
    }
    free(cur); free(copy); return 0;
}
static int parse_ref_bytes(const CvcBuf*b,int*born,uint8_t oid[32]){if(b->len==0){*born=0;memset(oid,0,32);return 0;}if(b->len!=65||b->data[64]!='\n'||!cvc_ascii_hex((const char*)b->data,64))return -1;for(size_t i=0;i<64;i++)if(b->data[i]>='A'&&b->data[i]<='F')return -1;char h[65];memcpy(h,b->data,64);h[64]=0;if(!cvc_hex_decode_32(h,oid))return -1;*born=1;return 0;}
int cvc_branch_read(CvcRepo*r,const char*name,int*born,uint8_t oid[32]){if(!cvc_branch_name_valid(name))return cvc_errorf("invalid branch name");char*ib=cvc_path_join(r->cvc,"refs/heads");if(validate_intermediate_dirs(ib,name)<0){free(ib);return -1;}free(ib);char*heads=cvc_path_join(r->cvc,"refs/heads"),*p=cvc_path_join(heads,name);free(heads);if(require_reg(p,"branch ref")<0){free(p);return -1;}CvcBuf b;if(cvc_read_file_nofollow(p,&b)<0){int e=errno;free(p);return cvc_errorf("cannot read branch ref: %s",strerror(e));}free(p);if(parse_ref_bytes(&b,born,oid)<0){cvc_buf_free(&b);return cvc_errorf("repository integrity: malformed branch ref %s",name);}cvc_buf_free(&b);if(*born){CvcObjType t;CvcBuf q;if(cvc_object_read(r->cvc,oid,&t,&q)<0)return -1;if(t!=CVC_OBJ_COMMIT){cvc_buf_free(&q);return cvc_errorf("branch ref does not point to commit");}CvcCommit c;if(cvc_commit_parse(q.data,q.len,&c)<0){cvc_buf_free(&q);return cvc_errorf("branch ref points to malformed commit");}cvc_commit_free(&c);cvc_buf_free(&q);}return 0;}
static int read_head(CvcRepo*r){char*p=cvc_path_join(r->cvc,"HEAD");CvcBuf b;if(cvc_read_file_nofollow(p,&b)<0){free(p);return cvc_errorf("cannot read HEAD");}free(p);static const char pre[]="ref: refs/heads/";if(b.len<=sizeof(pre)||memcmp(b.data,pre,sizeof(pre)-1)||b.data[b.len-1]!='\n'||memchr(b.data,'\0',b.len)){cvc_buf_free(&b);return cvc_errorf("repository integrity: malformed HEAD");}size_t nl=b.len-(sizeof(pre)-1)-1;char*name=cvc_xstrndup((const char*)b.data+sizeof(pre)-1,nl);cvc_buf_free(&b);if(!cvc_branch_name_valid(name)){free(name);return cvc_errorf("repository integrity: invalid HEAD branch name");}int born;uint8_t id[32];if(cvc_branch_read(r,name,&born,id)<0){free(name);return -1;}free(r->branch);r->branch=name;r->born=born;if(born)memcpy(r->head,id,32);else memset(r->head,0,32);return 0;}
static int acquire_lock(CvcRepo*r,int wr){char*p=cvc_path_join(r->cvc,"lock");struct stat st;if(lstat(p,&st)<0||!S_ISREG(st.st_mode)||st.st_size!=0){free(p);return cvc_errorf("repository integrity: lock must be zero-length regular file");}int fd=open(p,(wr?O_RDWR:O_RDONLY)|O_CLOEXEC|O_NOFOLLOW);free(p);if(fd<0)return cvc_errorf("cannot open repository lock");struct flock fl;memset(&fl,0,sizeof(fl));fl.l_type=(short)(wr?F_WRLCK:F_RDLCK);fl.l_whence=SEEK_SET;fl.l_start=0;fl.l_len=0;if(fcntl(fd,F_SETLK,&fl)<0){int e=errno;close(fd);if(e==EACCES||e==EAGAIN)return cvc_errorf("repository busy");return cvc_errorf("cannot acquire repository lock: %s",strerror(e));}r->lock_fd=fd;r->write_lock=wr;return 0;}
int cvc_repo_open(CvcRepo*r,int wr){memset(r,0,sizeof(*r));r->lock_fd=-1;r->root=find_root();if(!r->root)return cvc_errorf("not inside a CVC repository");r->cvc=cvc_path_join(r->root,".cvc");char*refs=cvc_path_join(r->cvc,"refs"),*heads=cvc_path_join(refs,"heads"),*objs=cvc_path_join(r->cvc,"objects"),*state=cvc_path_join(r->cvc,"state"),*head=cvc_path_join(r->cvc,"HEAD"),*cfg=cvc_path_join(r->cvc,"config.json"),*lock=cvc_path_join(r->cvc,"lock");int ok=0;if(require_dir(r->cvc,".cvc")<0||require_dir(refs,"refs")<0||require_dir(heads,"refs/heads")<0||require_dir(objs,"objects")<0||require_dir(state,"state")<0||require_reg(head,"HEAD")<0||require_reg(cfg,"config.json")<0||require_reg(lock,"lock")<0)ok=-1;free(refs);free(heads);free(objs);free(state);free(head);free(lock);if(ok<0){free(cfg);cvc_repo_close(r);return -1;}if(acquire_lock(r,wr)<0){free(cfg);cvc_repo_close(r);return -1;}if(cvc_config_load(cfg,&r->config)<0){free(cfg);cvc_repo_close(r);return -1;}free(cfg);if(read_head(r)<0){cvc_repo_close(r);return -1;}return 0;}
void cvc_repo_close(CvcRepo*r){if(r->lock_fd>=0)close(r->lock_fd);r->lock_fd=-1;free(r->root);free(r->cvc);free(r->branch);r->root=r->cvc=r->branch=NULL;if(r->config.tracking_include.v||r->config.tracking_exclude.v||r->config.diffstat_include.v||r->config.diffstat_exclude.v)cvc_config_free(&r->config);memset(&r->config,0,sizeof(r->config));}
int cvc_repo_refresh_head(CvcRepo*r){return read_head(r);}

int cvc_repo_atomic_meta_write(CvcRepo*r,const char*dest,const void*data,size_t len,mode_t mode){char*state=cvc_path_join(r->cvc,"state");size_t ns=strlen(state);char*tmp=cvc_xmalloc(ns+40);snprintf(tmp,ns+40,"%s/.meta-tmp-XXXXXX",state);int fd=mkstemp(tmp);if(fd<0){free(state);free(tmp);return cvc_errorf("cannot create metadata temp");}int rc=0,e=0;if(fchmod(fd,mode)<0||cvc_write_all(fd,data,len)<0||fsync(fd)<0){rc=-1;e=errno;}if(close(fd)<0&&rc==0){rc=-1;e=errno;}if(rc==0&&rename(tmp,dest)<0){rc=-1;e=errno;}if(rc==0&&cvc_fsync_parent(dest)<0){rc=-1;e=errno;}if(rc<0)unlink(tmp);free(state);free(tmp);if(rc<0){errno=e;return cvc_errorf("atomic metadata update failed: %s",strerror(e));}return 0;}
static char*ref_path(CvcRepo*r,const char*name){char*h=cvc_path_join(r->cvc,"refs/heads");char*p=cvc_path_join(h,name);free(h);return p;}
int cvc_branch_write(CvcRepo*r,const char*name,int born,const uint8_t oid[32]){char*p=ref_path(r,name);char b[65];size_t n=0;if(born){cvc_hex_encode(oid,32,b);b[64]='\n';n=65;}int rc=cvc_repo_atomic_meta_write(r,p,born?b:"",n,0666);free(p);return rc;}
int cvc_head_write_branch(CvcRepo*r,const char*name){CvcBuf b;cvc_buf_init(&b);cvc_buf_printf(&b,"ref: refs/heads/%s\n",name);char*p=cvc_path_join(r->cvc,"HEAD");int rc=cvc_repo_atomic_meta_write(r,p,b.data,b.len,0666);free(p);cvc_buf_free(&b);return rc;}

static int branch_walk(CvcRepo*r,const char*abs,const char*rel,CvcStrVec*out){DIR*d=opendir(abs);if(!d)return cvc_errorf("cannot enumerate branch refs");struct dirent*de;int rc=0;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;char*ap=cvc_path_join(abs,de->d_name),*rp=rel[0]?cvc_path_join(rel,de->d_name):cvc_xstrdup(de->d_name);struct stat st;if(lstat(ap,&st)<0){free(ap);free(rp);rc=-1;break;}if(S_ISDIR(st.st_mode)){if(branch_walk(r,ap,rp,out)<0)rc=-1;}else if(S_ISREG(st.st_mode)){if(cvc_branch_name_valid(rp))cvc_strvec_push(out,rp);else if(strncmp(de->d_name,".meta-tmp-",10)!=0)cvc_warnf("ignoring non-branch ref-side file %s",rp);}else{cvc_errorf("repository integrity: unsafe branch-ref entry %s",rp);rc=-1;}free(ap);free(rp);if(rc<0)break;}closedir(d);return rc;}
int cvc_branch_list(CvcRepo*r,CvcStrVec*out){cvc_strvec_init(out);char*h=cvc_path_join(r->cvc,"refs/heads");int rc=branch_walk(r,h,"",out);free(h);if(rc<0){cvc_strvec_free(out);return -1;}cvc_strvec_sort(out);for(size_t i=0;i<out->n;i++){int born;uint8_t id[32];if(cvc_branch_read(r,out->v[i],&born,id)<0){cvc_strvec_free(out);return -1;}}return 0;}
static int ensure_ref_parents(CvcRepo*r,const char*name){char*h=cvc_path_join(r->cvc,"refs/heads");char*tmp=cvc_xstrdup(name);char*save=tmp;char*slash;while((slash=strchr(tmp,'/'))){*slash=0;char*p=cvc_path_join(h,save);struct stat st;if(lstat(p,&st)==0){if(!S_ISDIR(st.st_mode)){free(p);free(h);free(save);return cvc_errorf("branch namespace prefix collision");}}else if(errno==ENOENT){if(mkdir(p,0777)<0){int e=errno;free(p);free(h);free(save);return cvc_errorf("cannot create ref directory: %s",strerror(e));}}else{free(p);free(h);free(save);return cvc_errorf("cannot inspect ref namespace");}free(p);*slash='/';tmp=slash+1;}free(h);free(save);return 0;}
static int dir_empty(const char*p){DIR*d=opendir(p);if(!d)return 0;int empty=1;struct dirent*de;while((de=readdir(d)))if(strcmp(de->d_name,".")&&strcmp(de->d_name,"..")){empty=0;break;}closedir(d);return empty;}
int cvc_branch_create(CvcRepo*r,const char*name){if(!cvc_branch_name_valid(name))return cvc_errorf("invalid branch name");if(ensure_ref_parents(r,name)<0)return -1;char*p=ref_path(r,name);struct stat st;if(lstat(p,&st)==0){if(S_ISDIR(st.st_mode)&&dir_empty(p)){if(rmdir(p)<0){free(p);return cvc_errorf("cannot remove stale ref directory");}}else{free(p);return cvc_errorf("branch already exists or namespace collision");}}else if(errno!=ENOENT){free(p);return cvc_errorf("cannot inspect branch destination");}int fd=open(p,O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC|O_NOFOLLOW,0666);if(fd<0){free(p);return cvc_errorf("cannot create branch ref: %s",strerror(errno));}char h[65];size_t n=0;if(r->born){cvc_hex_encode(r->head,32,h);h[64]='\n';n=65;}int rc=0,e=0;if(n&&cvc_write_all(fd,h,n)<0)rc=-1,e=errno;if(fsync(fd)<0&&rc==0)rc=-1,e=errno;if(close(fd)<0&&rc==0)rc=-1,e=errno;if(rc==0&&cvc_fsync_parent(p)<0)rc=-1,e=errno;if(rc<0)unlink(p);free(p);if(rc<0){errno=e;return cvc_errorf("branch creation failed: %s",strerror(e));}return 0;}

typedef struct { uint8_t *p; size_t n,cap; } Oids;
static void oids_free(Oids*v){free(v->p);memset(v,0,sizeof(*v));}
static int oids_has(const Oids*v,const uint8_t id[32]){for(size_t i=0;i<v->n;i++)if(!memcmp(v->p+i*32,id,32))return 1;return 0;}
static void oids_add(Oids*v,const uint8_t id[32]){if(oids_has(v,id))return;if(v->n==v->cap){v->cap=v->cap?v->cap*2:32;v->p=cvc_xrealloc(v->p,v->cap*32);}memcpy(v->p+v->n*32,id,32);v->n++;}
static int load_commit(CvcRepo*r,const uint8_t id[32],CvcCommit*c){CvcObjType t;CvcBuf p;if(cvc_object_read(r->cvc,id,&t,&p)<0)return -1;if(t!=CVC_OBJ_COMMIT){cvc_buf_free(&p);return cvc_errorf("expected commit object");}if(cvc_commit_parse(p.data,p.len,c)<0){cvc_buf_free(&p);return cvc_errorf("malformed commit object");}cvc_buf_free(&p);return 0;}
static int collect_anc(CvcRepo*r,const uint8_t start[32],Oids*out){memset(out,0,sizeof(*out));Oids q={0};oids_add(&q,start);for(size_t qi=0;qi<q.n;qi++){uint8_t*id=q.p+qi*32;if(oids_has(out,id))continue;oids_add(out,id);CvcCommit c;if(load_commit(r,id,&c)<0){oids_free(&q);oids_free(out);return -1;}for(unsigned j=0;j<c.parent_count;j++)oids_add(&q,c.parents[j]);cvc_commit_free(&c);}oids_free(&q);return 0;}
int cvc_commit_is_ancestor(CvcRepo*r,const uint8_t anc[32],const uint8_t desc[32],int*yes){Oids a;if(collect_anc(r,desc,&a)<0)return -1;*yes=oids_has(&a,anc);oids_free(&a);return 0;}
int cvc_merge_base(CvcRepo*r,const uint8_t a[32],const uint8_t b[32],uint8_t out[32]){Oids A,B;if(collect_anc(r,a,&A)<0)return -1;if(collect_anc(r,b,&B)<0){oids_free(&A);return -1;}Oids C={0};for(size_t i=0;i<A.n;i++)if(oids_has(&B,A.p+i*32))oids_add(&C,A.p+i*32);if(!C.n){oids_free(&A);oids_free(&B);return cvc_errorf("no common ancestor");}int found=0;uint8_t best[32];for(size_t i=0;i<C.n;i++){uint8_t*ci=C.p+i*32;int dominated=0;for(size_t j=0;j<C.n&&!dominated;j++)if(i!=j){int yes;if(cvc_commit_is_ancestor(r,ci,C.p+j*32,&yes)<0){oids_free(&A);oids_free(&B);oids_free(&C);return -1;}if(yes)dominated=1;}if(!dominated&&(!found||memcmp(ci,best,32)<0)){memcpy(best,ci,32);found=1;}}oids_free(&A);oids_free(&B);oids_free(&C);if(!found)return cvc_errorf("cannot select merge base");memcpy(out,best,32);return 0;}
int cvc_branch_delete(CvcRepo*r,const char*name,int*warn_unique){*warn_unique=0;if(!cvc_branch_name_valid(name))return cvc_errorf("invalid branch name");if(!strcmp(name,r->branch))return cvc_errorf("cannot delete current branch");int born;uint8_t id[32];if(cvc_branch_read(r,name,&born,id)<0)return -1;if(born){CvcStrVec bs;if(cvc_branch_list(r,&bs)<0)return -1;int reachable=0;for(size_t i=0;i<bs.n&&!reachable;i++)if(strcmp(bs.v[i],name)){int ob;uint8_t other[32];if(cvc_branch_read(r,bs.v[i],&ob,other)<0){cvc_strvec_free(&bs);return -1;}if(ob){int yes;if(cvc_commit_is_ancestor(r,id,other,&yes)<0){cvc_strvec_free(&bs);return -1;}if(yes)reachable=1;}}cvc_strvec_free(&bs);if(!reachable)*warn_unique=1;}char*p=ref_path(r,name);if(unlink(p)<0){int e=errno;free(p);return cvc_errorf("cannot delete branch: %s",strerror(e));}if(cvc_fsync_parent(p)<0){free(p);return cvc_errorf("cannot sync branch deletion");}/* prune empty parents up to heads */char*heads=cvc_path_join(r->cvc,"refs/heads");char*d=cvc_path_dirname(p);while(strcmp(d,heads)&&cvc_path_is_prefix(heads,d)&&dir_empty(d)){if(rmdir(d)<0)break;char*u=cvc_path_dirname(d);free(d);d=u;}free(d);free(heads);free(p);return 0;}

static int branch_exists_raw(CvcRepo*r,const char*name){if(!cvc_branch_name_valid(name))return 0;char*p=ref_path(r,name);struct stat st;int y=lstat(p,&st)==0&&S_ISREG(st.st_mode);free(p);return y;}
static void lowerhex(char*s){for(;*s;s++)if(*s>='A'&&*s<='F')*s=(char)(*s-'A'+'a');}
int cvc_resolve_revision(CvcRepo*r,const char*rev,uint8_t oid[32]){if(branch_exists_raw(r,rev)){int born;if(cvc_branch_read(r,rev,&born,oid)<0)return -1;if(!born)return cvc_errorf("branch '%s' is unborn",rev);return 0;}size_t n=strlen(rev);if(n==64&&cvc_ascii_hex(rev,n)){char*h=cvc_xstrdup(rev);lowerhex(h);uint8_t id[32];cvc_hex_decode_32(h,id);free(h);CvcCommit c;if(load_commit(r,id,&c)<0)return -1;cvc_commit_free(&c);memcpy(oid,id,32);return 0;}if(n<8||n>=64||!cvc_ascii_hex(rev,n))return cvc_errorf("unknown revision '%s'",rev);char*pre=cvc_xstrdup(rev);lowerhex(pre);char*objs=cvc_path_join(r->cvc,"objects");DIR*d1=opendir(objs);if(!d1){free(pre);free(objs);return cvc_errorf("cannot scan object store");}int matches=0;uint8_t found[32];struct dirent*a;int rc=0;while((a=readdir(d1))&&rc==0){if(strlen(a->d_name)!=2||!cvc_ascii_hex(a->d_name,2))continue;char*dp=cvc_path_join(objs,a->d_name);struct stat ds;if(lstat(dp,&ds)<0||!S_ISDIR(ds.st_mode)){free(dp);continue;}DIR*d2=opendir(dp);if(!d2){free(dp);rc=-1;break;}struct dirent*b;while((b=readdir(d2))){if(strlen(b->d_name)!=62||!cvc_ascii_hex(b->d_name,62))continue;char full[65];memcpy(full,a->d_name,2);memcpy(full+2,b->d_name,62);full[64]=0;lowerhex(full);if(strncmp(full,pre,n))continue;uint8_t id[32];cvc_hex_decode_32(full,id);CvcObjType t;CvcBuf p;if(cvc_object_read(r->cvc,id,&t,&p)<0){rc=-1;break;}if(t==CVC_OBJ_COMMIT){CvcCommit c;if(cvc_commit_parse(p.data,p.len,&c)<0){cvc_buf_free(&p);rc=cvc_errorf("corrupt commit candidate");break;}cvc_commit_free(&c);matches++;memcpy(found,id,32);}cvc_buf_free(&p);}closedir(d2);free(dp);}closedir(d1);free(pre);free(objs);if(rc<0)return -1;if(matches==0)return cvc_errorf("unknown revision prefix");if(matches>1)return cvc_errorf("ambiguous revision prefix");memcpy(oid,found,32);return 0;}
int cvc_get_timestamp(int64_t*out){const char*s=getenv("CVC_TEST_TIMESTAMP");if(s){if(!cvc_parse_i64_timestamp(s,out))return cvc_errorf("invalid CVC_TEST_TIMESTAMP");return 0;}time_t t=time(NULL);if(t==(time_t)-1)return cvc_errorf("cannot read wall clock");if(sizeof(time_t)>sizeof(int64_t)){/* practical platforms won't hit this */}*out=(int64_t)t;return 0;}
